fn less(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since we assume `a.len() == b.len()`, zipping them will iterate exactly over all pairs.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x < y)
     .collect()
}

