    #[test]
    fn test_less_basic() {
        let a = vec![-1, 0, 5, 10];
        let b = vec![0, 0, 3, 10];
        // -1 < 0 == true
        //  0 < 0 == false
        //  5 < 3 == false
        // 10 < 10 == false
        assert_eq!(less(a, b), vec![true, false, false, false]);
    }

    #[test]
